import AppKit
import SwiftUI

/// The app icons a user can pick in Settings → App-Icon.
/// Sources: `Resources/Icons/<id>.icon` (generated by `scripts/make-icons.swift`), pre-rendered to
/// `<id>-light.png` / `<id>-dark.png` by `scripts/render-icon-previews.sh`.
enum AppIconChoice: String, CaseIterable, Codable, Identifiable {
    case tile, plusOne = "plus-one", tally, roller

    var id: String { rawValue }

    var title: LocalizedStringKey {
        switch self {
        case .tile: "Tile"
        case .plusOne: "Plus One"
        case .tally: "Tally"
        case .roller: "Roller"
        }
    }
}

/// Applies the chosen icon.
///
/// `tile` is compiled into the bundle (`Assets.car`), so macOS renders it live with Liquid Glass
/// in every icon style. The alternatives are set as a custom Finder icon on the app bundle
/// (`NSWorkspace.setIcon`), using the PNG that matches the current icon style (light/dark).
@MainActor
enum AppIconManager {
    static func image(for choice: AppIconChoice, dark: Bool = systemIconsAreDark) -> NSImage? {
        let name = "\(choice.rawValue)-\(dark ? "dark" : "light")"
        guard let url = Bundle.main.url(forResource: name, withExtension: "png", subdirectory: "Icons") else { return nil }
        return NSImage(contentsOf: url)
    }

    /// Whether macOS currently draws app icons in the dark style.
    static var systemIconsAreDark: Bool {
        let theme = UserDefaults.standard.string(forKey: "AppleIconAppearanceTheme") ?? ""
        if theme.contains("Dark") { return true }
        if theme.contains("Light") { return false }
        return NSApp.effectiveAppearance.bestMatch(from: [.darkAqua, .aqua]) == .darkAqua
    }

    /// Returns false if the icon could not be written to the bundle (e.g. no write access).
    @discardableResult
    static func apply(_ choice: AppIconChoice) -> Bool {
        let bundlePath = Bundle.main.bundlePath
        guard bundlePath.hasSuffix(".app") else { return true } // `swift run`: nothing to set
        let hasCustomIcon = FileManager.default.fileExists(atPath: bundlePath + "/Icon\r")

        if choice == .tile {
            NSApp.applicationIconImage = nil
            guard hasCustomIcon else { return true }
            let ok = NSWorkspace.shared.setIcon(nil, forFile: bundlePath, options: [])
            // Leave no Finder metadata behind, so the bundle passes strict signature checks again.
            removexattr(bundlePath, "com.apple.FinderInfo", 0)
            NSWorkspace.shared.noteFileSystemChanged(bundlePath)
            return ok
        }
        guard let image = image(for: choice) else { return false }
        NSApp.applicationIconImage = image
        let ok = NSWorkspace.shared.setIcon(image, forFile: bundlePath, options: [])
        NSWorkspace.shared.noteFileSystemChanged(bundlePath)
        return ok
    }
}
